<?php
namespace App\Http\Controllers;use App\Models\{CreatorProfile,User,UserBadge};use Illuminate\Http\Request;use Illuminate\Support\Str;
class SupporterController extends Controller {
 public function show(User $user){$user->load(['badges','creatorProfile']);$stats=['predictions'=>$user->predictions()->count(),'points'=>$user->predictions()->sum('points_earned'),'leagues'=>$user->predictionGroups()->count()];return view('supporters.show',compact('user','stats'));}
 public function updateIdentity(Request $r){$data=$r->validate(['username'=>'nullable|alpha_dash|max:30|unique:users,username,'.auth()->id(),'country_code'=>'nullable|string|max:3','city'=>'nullable|string|max:80','war_faction'=>'nullable|in:legion,horde,vikings,hoplites,outlaws','bio'=>'nullable|string|max:280']);auth()->user()->update($data);return back()->with('success','Supporter identity saved.');}
 public function claimDaily(){ $u=auth()->user();$today=now()->toDateString();if(optional($u->last_active_on)->toDateString()===$today)return back()->with('success','Today’s flame is already lit.');$yesterday=now()->subDay()->toDateString();$streak=optional($u->last_active_on)->toDateString()===$yesterday?$u->current_streak+1:1;$u->update(['last_active_on'=>$today,'current_streak'=>$streak,'best_streak'=>max($u->best_streak,$streak),'matchday_points'=>$u->matchday_points+10]);if($streak>=7)UserBadge::firstOrCreate(['user_id'=>$u->id,'badge'=>'seven_day_watch'],['label'=>'Seven-Day Watch','awarded_at'=>now()]);return back()->with('success','Flame lit: +10 Matchday Points.');}
 public function applyCreator(Request $r){$d=$r->validate(['display_name'=>'required|string|max:80','bio'=>'required|string|min:40|max:800','speciality'=>'required|string|max:100','social_url'=>'nullable|url|max:255']);CreatorProfile::updateOrCreate(['user_id'=>auth()->id()],$d+['slug'=>Str::slug($d['display_name']).'-'.auth()->id(),'status'=>'pending']);return back()->with('success','Application sent to the editorial council.');}
}
